// ─── Encyclopédie Dinosaures MaxPlay ───
// Données riches · FR = canon inline (i18n : overlay js/dinos-i18n.js) · adapté 3-5 ans · count = length (jamais en dur)
// Catégories : carnivores · herbivores · piscivores · omnivores

// ─── Familles (2e catégorisation) ───
// label = nom simple (visible en gros) · savant = le vrai mot des savants (sous-titre discret)
// explic = texte lu à voix haute au clic (décompo grecque + pourquoi ce nom + qui est connu + ce qu'ils mangent)
//          textes validés Papa Yann + panel 3 LLM (Grok/Kimi/DeepSeek) le 2026-06-01
// sci = nom scientifique pur (GROS titre de la carte, c'est le vrai mot des savants)
// label = surnom simple (sous-titre) · sci_sens = origine grecque/latine COURTE (dite en entrant)
// explic = explication longue complète (décompo + qui est connu + régime), lue au clic 🔊
const DINO_FAMILLES = [
  { id: 'trex',       sci: 'Théropodes',     label: 'les chasseurs à deux pattes', savant: 'les théropodes',          emoji: '🦖', desc: 'Ils marchent sur deux pattes et chassent',  color: '#c0392b', bg: 'linear-gradient(135deg,#7b0000,#c0392b)',
    sci_sens: 'En grec, théro veut dire bête sauvage, et pode veut dire pied.',
    explic: 'Théropodes ! En grec, théro veut dire bête sauvage, et pode veut dire pied. On les a appelés comme ça parce qu\'ils marchaient sur deux grandes pattes arrière, comme les oiseaux d\'aujourd\'hui — pas sur quatre ! Presque tous mangeaient de la viande. Les plus connus : le T-Rex, le Spinosaure, le Giganotosaure.' },
  { id: 'cou_long',   sci: 'Sauropodes',     label: 'les géants à long cou',       savant: 'les sauropodes',          emoji: '🦒', desc: 'Le cou immense pour manger tout en haut',   color: '#27ae60', bg: 'linear-gradient(135deg,#0a4a1e,#27ae60)',
    sci_sens: 'En grec, sauro veut dire lézard, et pode veut dire pied.',
    explic: 'Sauropodes ! En grec, sauro veut dire lézard, et pode veut dire pied. Ce sont les plus grands animaux qui ont marché sur Terre ! Quatre pattes comme des poteaux, un cou immense pour attraper les feuilles tout en haut des arbres. Ils mangeaient seulement des plantes. Les stars : le Diplodocus, le Brachiosaure, le Brontosaure.' },
  { id: 'arme',       sci: 'Thyréophores',   label: 'les armures à pics',          savant: 'les thyréophores',        emoji: '🦴', desc: 'Plaques, piques et queue-massue',           color: '#7f8c8d', bg: 'linear-gradient(135deg,#2c3e50,#7f8c8d)',
    sci_sens: 'En grec, thyréo veut dire bouclier, et phore veut dire porter.',
    explic: 'Thyréophores ! En grec, thyréo veut dire bouclier, et phore veut dire porter : les porteurs de bouclier. Leur dos était couvert de plaques, de piques et d\'os durs comme une armure pour se protéger des chasseurs. Ils broutaient les plantes. Les connus : le Stégosaure, avec des plaques sur le dos, et l\'Ankylosaure, avec une grosse boule osseuse au bout de la queue.' },
  { id: 'cornu',      sci: 'Cératopsiens',   label: 'les cornus à collerette',     savant: 'les cératopsiens',        emoji: '🛡️', desc: 'Des cornes et une grande collerette',      color: '#f39c12', bg: 'linear-gradient(135deg,#7a5000,#f39c12)',
    sci_sens: 'En grec, cérat veut dire corne, et ops veut dire face.',
    explic: 'Cératopsiens ! En grec, cérat veut dire corne, et ops veut dire face : les faces à cornes. Ils avaient des cornes sur la tête et une grande collerette d\'os derrière le crâne, comme un bouclier autour du cou. Ils mangeaient des plantes. La super-star : le Tricératops et son cousin le Torosaure.' },
  { id: 'bec',        sci: 'Ornithopodes',   label: 'les becs de canard',          savant: 'les ornithopodes',        emoji: '🦆', desc: 'Un bec plat et de grands troupeaux',        color: '#8e44ad', bg: 'linear-gradient(135deg,#4a0080,#8e44ad)',
    sci_sens: 'En grec, ornitho veut dire oiseau, et pode veut dire pied.',
    explic: 'Ornithopodes ! En grec, ornitho veut dire oiseau, et pode veut dire pied : les pieds d\'oiseau. Leurs pattes ressemblaient à celles des oiseaux. Ils avaient un large bec plat comme un canard pour brouter, et vivaient en grands troupeaux. Tous mangeaient des plantes. Les connus : le Parasaurolophus et l\'Iguanodon.' },
  { id: 'raptor',     sci: 'Dromæosaures',   label: 'les chasseurs à griffes',     savant: 'les dromæosaures',        emoji: '🦅', desc: 'Griffes-faucilles et chasseurs malins',     color: '#e67e22', bg: 'linear-gradient(135deg,#7a3000,#e67e22)',
    sci_sens: 'En grec, dromæo veut dire qui court, et saure, le lézard.',
    explic: 'Dromæosaures ! En grec, dromæo veut dire qui court vite, et saure, le lézard : les lézards coureurs. Ce sont des cousins des théropodes, mais plus petits, rapides et malins, avec une grande griffe recourbée comme un croissant à chaque pied pour attraper leurs proies. Ils mangeaient de la viande. Les vedettes : le Vélociraptor et le grand Deinonychus.' },
  { id: 'pterosaures', sci: 'Ptérosaures',    label: 'les reptiles volants',        savant: 'les ptérosaures',         emoji: '🦅', desc: 'De grandes ailes de peau pour voler',      color: '#2980b9', bg: 'linear-gradient(135deg,#1a5276,#2980b9)',
    sci_sens: 'En grec, ptéro veut dire aile, et saure, le lézard.',
    explic: 'Ptérosaures ! En grec, ptéro veut dire aile, et saure, le lézard : les lézards ailés. Attention, ce ne sont pas des dinosaures, mais leurs cousins ! Ils planaient sur de grandes ailes de peau, comme un cerf-volant vivant. Les connus : le Ptéranodon, et l\'immense Quetzalcoatlus, grand comme un petit avion !' },
  { id: 'enaliosaures', sci: 'Énaliosaures', label: 'les reptiles géants de la mer', savant: 'les énaliosaures', emoji: '🌊', desc: 'Pas des dinosaures — des reptiles géants qui nageaient !', color: '#16607a', bg: 'linear-gradient(135deg,#0a3d52,#16607a)',
    sci_sens: 'En grec, enalio veut dire de la mer, et saure veut dire lézard.',
    explic: 'Énaliosaures ! En grec, enalio veut dire de la mer, et saure veut dire lézard : les lézards de la mer. Attention, ce ne sont PAS des dinosaures ! Ce sont des reptiles géants qui vivaient en même temps, mais dans la MER. Certains avaient un très long cou, d\'autres une grande bouche de chasseur, et l\'un d\'eux était une tortue géante ! Les stars : l\'Élasmosaure au long cou, le Liopleurodon chasseur, la tortue géante Archélon, et les ichtyosaures Shonisaure et Shastasaure.' },
  { id: 'volant',     sci: 'Avant les dinosaures', label: 'le cousin d\'avant les dinos', savant: 'avant les dinosaures', emoji: '⏳', desc: 'Il vivait bien avant les dinosaures !', color: '#8e6e3c', bg: 'linear-gradient(135deg,#4a3818,#8e6e3c)',
    sci_sens: 'Surprise : ils vivaient AVANT les dinosaures !',
    explic: 'Attention, ce ne sont PAS des dinosaures ! Ils vivaient très, très longtemps AVANT eux. Et le plus fou : ce sont des cousins lointains des animaux à poils — donc un peu de toi ! Il y a le Dimétrodon et l\'Édaphosaure, qui portaient une grande voile sur le dos ; le Gorgonops, un chasseur aux dents en sabre ; le petit Lystrosaure, qui a survécu à la plus grosse catastrophe de la Terre ; et le Moschops, au crâne épais comme un casque.' },
  { id: 'mammiferes', sci: 'Mammifères',     label: 'les bêtes à poils d\'après les dinos', savant: 'les mammifères',    emoji: '🦣', desc: 'Après les dinos : les géants à poils',       color: '#8d6e63', bg: 'linear-gradient(135deg,#3e2723,#8d6e63)',
    sci_sens: 'Un mammifère, c\'est un animal à poils dont la maman fait du lait pour ses petits — comme toi !',
    explic: 'Les mammifères ! Ce sont des animaux à poils, dont la maman donne du lait à ses bébés — comme le chat, le chien, ou toi ! Quand la grande météorite a fait disparaître les dinosaures, ce sont EUX qui ont pris toute la place sur la Terre. Certains sont devenus énormes ! Les stars : le Mammouth laineux tout poilu, le Smilodon et ses dents géantes, et le Paraceratherium, le plus grand animal à poils qui ait jamais marché sur la Terre.' },
  { id: 'oiseaux',    sci: 'Oiseaux',        label: 'les oiseaux géants qui ne volaient pas', savant: 'les oiseaux',    emoji: '🦤', desc: 'Des oiseaux géants chasseurs, sans voler',   color: '#d68910', bg: 'linear-gradient(135deg,#7a4a00,#d68910)',
    sci_sens: 'Les oiseaux sont les cousins vivants des dinosaures — les seuls qui restent !',
    explic: 'Les oiseaux ! Sais-tu un secret ? Les oiseaux sont les petits-cousins des dinosaures — c\'est la seule famille de dinosaures qui existe encore aujourd\'hui ! Mais après la météorite, certains oiseaux sont devenus GÉANTS, trop lourds pour voler. Ils couraient sur deux grandes pattes pour chasser, avec un bec énorme. La star : le Titanis, l\'oiseau-terreur !' },
];

